package com.keplerslicer.app;

import android.content.Context;
import com.keplerslicer.app.settings.PresetRepository;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

/** Exercises production snapshot, isolation, scope and fingerprint logic with JVM asset/preferences adapters. */
public final class SettingsStateTest {
    private static int assertions;
    private interface Action{void run()throws Exception;}
    private static void check(boolean ok,String label){assertions++;if(!ok)throw new AssertionError(label);}
    private static void rejects(Action action,String label)throws Exception {try{action.run();throw new AssertionError(label);}catch(IOException expected){assertions++;}}
    public static void main(String[] args)throws Exception {
        File root=new File(args[0]),originalAssets=new File(args[1]);Files.createDirectories(root.toPath());File fixtureAssets=new File(root,"fixture-assets");Files.createDirectories(fixtureAssets.toPath());
        try(ZipOutputStream zip=new ZipOutputStream(Files.newOutputStream(new File(fixtureAssets,"kepler_profiles.zip").toPath()))){for(String vendor:new String[]{"VendorA","VendorB","VendorC"})entry(zip,vendor+".json","{}");entry(zip,"VendorA/machine/Printer.json","{\"type\":\"machine\",\"name\":\"Printer\",\"from\":\"system\",\"instantiation\":\"true\",\"printer_settings_id\":\"Printer\"}");entry(zip,"VendorB/process/Process.json","{\"type\":\"process\",\"name\":\"Process\",\"inherits\":\"Base Process\",\"from\":\"system\",\"instantiation\":\"true\",\"setting_id\":\"original\",\"print_settings_id\":\"Process\",\"layer_height\":\"0.2\"}");entry(zip,"VendorC/filament/Filament.json","{\"type\":\"filament\",\"name\":\"Filament\",\"from\":\"system\",\"instantiation\":\"true\"}");entry(zip,"OrcaFilamentLibrary.json","{}");}
        try(ZipOutputStream zip=new ZipOutputStream(Files.newOutputStream(new File(fixtureAssets,"upstream_resources.zip").toPath()))){entry(zip,"info/legacy_compatible_printers.json","{}");}
        Context fixtureContext=new Context(new File(root,"fixture-context"),fixtureAssets);
        JSONObject process=new JSONObject("{\"layer_height\":\"0.16\",\"name\":\"User name\",\"inherits\":\"User base\",\"from\":\"user\",\"unknown\":[1,true,null]}");Map<String,SettingsState.Overlay> overlays=new LinkedHashMap<>();overlays.put("printer",new SettingsState.Overlay("printer","VendorA/machine/Printer.json","Printer",new JSONObject("{\"nozzle_diameter\":[\"0.4\"]}")));overlays.put("process",new SettingsState.Overlay("process","VendorB/process/Process.json","Process",process));overlays.put("filament",new SettingsState.Overlay("filament","VendorC/filament/Filament.json","Filament",new JSONObject("{\"nozzle_temperature\":[\"215\"]}")));
        SettingsState.Snapshot snapshot=new SettingsState.Snapshot(overlays);String originalHash=snapshot.fingerprint;process.put("layer_height","9");overlays.clear();snapshot.overlays.get("process").effective.put("layer_height","8");check(snapshot.overlays.size()==3,"Snapshot owns its map");check(snapshot.overlays.get("process").values().getString("layer_height").equals("0.16"),"Snapshot owns immutable JSON content");
        Map<String,SettingsState.Overlay> reversed=new LinkedHashMap<>();for(String k:Arrays.asList("filament","process","printer"))reversed.put(k,snapshot.overlays.get(k));check(new SettingsState.Snapshot(reversed).fingerprint.equals(originalHash),"Map insertion order cannot change fingerprint");
        JSONObject changed=snapshot.overlays.get("process").values();changed.put("layer_height",0.16);Map<String,SettingsState.Overlay> typed=new LinkedHashMap<>(snapshot.overlays);typed.put("process",new SettingsState.Overlay("process","VendorB/process/Process.json","Process",changed));SettingsState.Snapshot changedSnapshot=new SettingsState.Snapshot(typed);check(!changedSnapshot.fingerprint.equals(originalHash),"String vs number changes snapshot identity");
        JSONObject arrayChange=snapshot.overlays.get("process").values();arrayChange.put("unknown",new JSONArray("[null,true,1]"));Map<String,SettingsState.Overlay> reordered=new LinkedHashMap<>(snapshot.overlays);reordered.put("process",new SettingsState.Overlay("process","VendorB/process/Process.json","Process",arrayChange));check(!new SettingsState.Snapshot(reordered).fingerprint.equals(originalHash),"Array order changes snapshot identity");
        rejects(()->new SettingsState.Overlay("process","../Vendor/process/a.json","a",new JSONObject()),"Traversal must fail");rejects(()->new SettingsState.Overlay("printer","Vendor/process/a.json","a",new JSONObject()),"Kind/path mismatch must fail");rejects(()->new SettingsState.Overlay("process","C:/Vendor/process/a.json","a",new JSONObject()),"Absolute path must fail");rejects(()->new SettingsState.Snapshot(Collections.singletonMap("printer",snapshot.overlays.get("process"))),"Overlay map key mismatch must fail");
        byte[] assetBefore=Files.readAllBytes(new File(fixtureAssets,"kepler_profiles.zip").toPath());CompatibilityResources prepared=CompatibilityResources.prepareTriple(fixtureContext,"VendorA","VendorB",null,snapshot);check(new File(prepared.data,"system/VendorC.json").isFile(),"Filament overlay vendor included in printer-only query");JSONObject installed=new JSONObject(Files.readString(new File(prepared.data,"system/VendorB/process/Process.json").toPath()));check(installed.getString("layer_height").equals("0.16"),"Frozen value installed");check(installed.getString("name").equals("Process"),"Original preset identity preserved");check(installed.getString("inherits").equals("Base Process"),"Original inheritance identity preserved");check(installed.getString("from").equals("system"),"Original origin preserved");check(installed.getString("setting_id").equals("original"),"Original setting ID preserved");check(installed.getJSONArray("unknown").isNull(2),"Unknown typed values preserved");check(Arrays.equals(assetBefore,Files.readAllBytes(new File(fixtureAssets,"kepler_profiles.zip").toPath())),"Original asset ZIP remains byte-identical");check(CompatibilityResources.prepareTriple(fixtureContext,"VendorA","VendorB",null,snapshot).data.equals(prepared.data),"Identical snapshot reuses immutable cache");check(!CompatibilityResources.prepareTriple(fixtureContext,"VendorA","VendorB",null,changedSnapshot).data.equals(prepared.data),"Changed snapshot receives a new isolated cache");check(snapshot.fingerprint.equals(originalHash),"Installing cannot mutate fingerprint");
        testObjects(fixtureContext,snapshot);
        Context real=new Context(new File(root,"real-context"),originalAssets);PresetRepository repo=SettingsState.repository(real);String nested=PresetRepository.systemId("printer","Elegoo","Elegoo Centauri 0.4 nozzle");PrinterProfileCatalog.Profile extra=PrinterProfileCatalog.systemProfile(repo.load(nested));check(extra.path.equals("Elegoo/machine/EC/Elegoo Centauri 0.4 nozzle.json"),"Nested machine path becomes a trusted selectable profile");SettingsState.select(real,nested);check(PrinterProfileCatalog.loadSelection(real).path.equals(extra.path),"Nested profile selection persists");String afinia=PresetRepository.systemId("printer","Afinia","Afinia H+1(HS) 0.4 nozzle");Context failed=new Context(new File(root,"failed-selection"),originalAssets);PrinterProfileCatalog.saveSelectionChecked(failed,extra);failed.failNextCommit(StorageNames.PROFILE_SELECTION);rejects(()->PrinterProfileCatalog.saveSelectionChecked(failed,PrinterProfileCatalog.systemProfile(repo.load(afinia))),"Failed disk commit must report error");check(PrinterProfileCatalog.loadSelection(failed).path.equals(extra.path),"Failed commit restores in-memory selection");
        SettingsState.select(real,afinia);SettingsState.select(real,PresetRepository.systemId("process","Afinia","0.12mm Fine @Afinia H+1(HS)"));SettingsState.select(real,PresetRepository.systemId("filament","Afinia","Afinia ABS+@HS"));SettingsState.Snapshot triple=SettingsState.capture(real);check(triple.overlays.size()==3,"System-only selection captures all three profiles");PresetRepository.Draft draft=repo.beginDraft(SettingsState.activeId(real,"process"));draft.set("layer_height","0.16");PresetRepository.Preset user=repo.saveAs(draft,"Test user process");SettingsState.select(real,user.id);SettingsState.Snapshot userSnapshot=SettingsState.capture(real);check(!triple.fingerprint.equals(userSnapshot.fingerprint),"User profile values participate in snapshot fingerprint");check(userSnapshot.overlays.get("process").path.equals(triple.overlays.get("process").path),"User overlay targets original selected system leaf");
        testSelectionTransactions(real,repo,user,extra);
        System.out.println("Settings state: "+assertions+" assertions passed");
    }
    private static void testSelectionTransactions(Context c,PresetRepository repo,PresetRepository.Preset selected,PrinterProfileCatalog.Profile anotherPrinter)throws Exception {
        android.content.SharedPreferences legacy=c.getSharedPreferences("kepler_process_overrides_v1",0),profile=c.getSharedPreferences(StorageNames.PRINT_PROFILES,0),prefs=c.getSharedPreferences("kepler_settings_v2",0);
        legacy.edit().putString("identity","legacy-id").putString("values","{\"layer_height\":0.19}").putInt("unrelated_number",8).putStringSet("unrelated_set",new java.util.HashSet<>(Arrays.asList("a","b"))).commit();int clears=ProcessOverridesStore.clears;
        SettingsState.select(c,selected.id);check(ProcessOverridesStore.clears==clears,"Reselecting active id never clears legacy overrides");check(legacy.getString("identity","").equals("legacy-id"),"Reselecting active id preserves legacy data");
        PresetRepository.Draft draft=repo.beginDraft(selected.id);draft.set("layer_height","0.18");PresetRepository.Preset sibling=repo.saveAs(draft,"Sibling user process");
        SettingsState.select(c,sibling.id);check(SettingsState.activeId(c,"process").equals(sibling.id),"Different user preset on same base is selected");check(ProcessOverridesStore.clears==clears,"Same system base does not clear legacy overrides");check(legacy.getString("identity","").equals("legacy-id"),"Same base retains overrides");
        String other=PresetRepository.systemId("process","Afinia","0.16mm Optimal @Afinia H+1(HS)");Map<String,?> originalProfile=profile.getAll(),originalPrefs=prefs.getAll(),originalLegacy=legacy.getAll();
        c.failNextCommit("kepler_settings_v2");rejects(()->SettingsState.select(c,other),"Failed user id commit reports failure");check(profile.getAll().equals(originalProfile),"Failed id commit restores system process selection");check(prefs.getAll().equals(originalPrefs),"Failed id commit restores user profile selection");check(legacy.getAll().equals(originalLegacy),"Failed selection restores legacy overrides");
        c.failNextCommit(StorageNames.PRINT_PROFILES);rejects(()->SettingsState.select(c,other),"Failed system process commit reports failure");check(profile.getAll().equals(originalProfile),"Failed system commit restores process prefs");check(prefs.getAll().equals(originalPrefs),"Failed system commit preserves user prefs");check(legacy.getAll().equals(originalLegacy),"Failed system commit restores legacy overrides");
        c.failNextCommit("kepler_process_overrides_v1");rejects(()->SettingsState.select(c,other),"Failed legacy clear reports failure");check(legacy.getAll().equals(originalLegacy),"Failed clear restores in-memory legacy overrides");check(profile.getAll().equals(originalProfile),"Failed clear does not change process");
        PrinterProfileCatalog.Profile printer=PrinterProfileCatalog.loadSelection(c);PrintProfileCatalog.Profile candidate=null;for(PrintProfileCatalog.Profile item:PrintProfileCatalog.load(c,"process"))if(item.name.equals("0.16mm Optimal @Afinia H+1(HS)")){candidate=item;break;}final PrintProfileCatalog.Profile chosen=candidate;
        Context malformed=new Context(new File(c.getCacheDir(),"typed-rollback"),new File(c.getCacheDir(),"unused"));android.content.SharedPreferences typed=malformed.getSharedPreferences(StorageNames.PRINT_PROFILES,0);typed.edit().putInt("process_vendor",9).putLong("process_name",17L).putFloat("process_path",1.25f).putStringSet("process_printer",new java.util.HashSet<>(Arrays.asList("a","b"))).putBoolean("unrelated",true).commit();Map<String,?> typedBefore=typed.getAll();malformed.failNextCommit(StorageNames.PRINT_PROFILES);rejects(()->PrintProfileCatalog.saveSelection(malformed,chosen,printer),"Catalog failure restores all supported preference types");check(typed.getAll().equals(typedBefore),"Catalog rollback retains typed values and unrelated keys");
        ProcessOverridesStore.beforeLock=()->PrinterProfileCatalog.saveSelection(c,anotherPrinter);rejects(()->SettingsState.select(c,other),"Concurrent printer change is rejected under lock");check(prefs.getAll().equals(originalPrefs),"Concurrent printer change cannot commit stale user selection");check(profile.getAll().equals(originalProfile),"Concurrent printer change cannot write stale process");PrinterProfileCatalog.saveSelection(c,printer);
        SettingsState.select(c,other);check(SettingsState.activeId(c,"process").equals(other),"Different system base selects new process");check(legacy.getAll().isEmpty(),"Different system base clears legacy overrides");
    }
    private static void testObjects(Context c,SettingsState.Snapshot profiles)throws Exception {
        c.getSharedPreferences("current_model",0).edit().putString("file","model-alpha.stl").putString("plate","-1").commit();CurrentModelStore.loads=0;ObjectSettingsStore.Snapshot initial=ObjectSettingsStore.current(c);check(initial.nativeObjectCount==1&&initial.isEmpty(),"STL is one native object");check(CurrentModelStore.loads==0,"STL object scope avoids unnecessary mesh import");JSONObject changes=new JSONObject().put("layer_height",0.24).put("enable_support",true).put("custom_vector",new JSONArray("[\"x\",null,3]"));ObjectSettingsStore.save(c,"model-alpha.stl",-1,1,changes);ObjectSettingsStore.Snapshot object=ObjectSettingsStore.snapshot(c);check(object.changes().get("layer_height") instanceof Number,"Typed number retained");check(object.changes().getBoolean("enable_support"),"Typed boolean retained");SettingsState.Snapshot applied=object.applied(profiles);check(applied.overlays.get("process").values().getDouble("layer_height")==0.24,"Single object's override overlays process value");check(applied.overlays.get("process").path.equals(profiles.overlays.get("process").path),"Original process ancestor path retained");check(applied.overlays.get("printer").values().toString().equals(profiles.overlays.get("printer").values().toString()),"Object changes cannot modify printer profile");String hash=object.fingerprint;object.values.put("layer_height",9);changes.put("layer_height",10);check(object.fingerprint.equals(hash)&&object.applied(profiles).overlays.get("process").values().getDouble("layer_height")==0.24,"Object snapshot immune to inspection/input mutations");rejects(()->ObjectSettingsStore.save(c,"model-alpha.stl",-1,2,new JSONObject()),"Multiple objects rejected");rejects(()->ObjectSettingsStore.save(c,"model-beta.stl",-1,1,new JSONObject()),"Stale model scope rejected");rejects(()->ObjectSettingsStore.save(c,"model-alpha.stl",-1,1,new JSONObject().put("inherits","Other")),"Preset identity cannot become an object override");
        check(!ObjectSettingsStore.key("model-alpha.3mf",0).equals(ObjectSettingsStore.key("model-alpha.3mf",1)),"Plate scope changes key");check(ObjectSettingsStore.load(c,"model-alpha.stl",0,1).length()==0,"Other plate receives no settings");check(ObjectSettingsStore.load(c,"model-beta.stl",-1,1).length()==0,"Other file receives no settings");ObjectSettingsStore.clear(c,"model-alpha.stl",-1);ObjectSettingsStore.Snapshot cleared=ObjectSettingsStore.snapshot(c);check(cleared.isEmpty()&&cleared.applied(profiles)==profiles,"Empty object scope does not change global snapshot");
        c.getSharedPreferences("current_model",0).edit().putString("file","model-obj.obj").putString("plate","-1").commit();CurrentModelStore.nextMetadata=new JSONObject("{\"objects\":[{},{}]}");rejects(()->ObjectSettingsStore.current(c),"Two native OBJ objects are explicitly unsupported");int count=CurrentModelStore.loads;check(ObjectSettingsStore.snapshot(c).isEmpty()&&CurrentModelStore.loads==count,"Empty record fingerprint avoids native metadata loading");CurrentModelStore.nextMetadata=new JSONObject("{\"project_data\":{\"objects\":[{}]}}");check(ObjectSettingsStore.current(c).nativeObjectCount==1,"Project metadata object count supported");
        JSONObject saved=new JSONObject().put("layer_height",0.22);ObjectSettingsStore.save(c,"model-obj.obj",-1,1,saved);android.content.SharedPreferences stored=c.getSharedPreferences("kepler_object_settings_v1",0);String id=ObjectSettingsStore.key("model-obj.obj",-1),proof=id+":native_object_count";check(Integer.valueOf(1).equals(stored.getAll().get(proof)),"Save atomically stores the verified native count beside its scope");count=CurrentModelStore.loads;CurrentModelStore.nextMetadata=null;ObjectSettingsStore.Snapshot fast=ObjectSettingsStore.snapshot(c);check(fast.nativeObjectCount==1&&fast.changes().getDouble("layer_height")==0.22,"Nonempty OBJ snapshot uses the persisted count proof");check(CurrentModelStore.loads==count,"Nonempty OBJ fingerprint never imports metadata or mesh");
        Map<String,?> beforeFailure=stored.getAll();c.failNextCommit("kepler_object_settings_v1");rejects(()->ObjectSettingsStore.save(c,"model-obj.obj",-1,1,new JSONObject().put("layer_height",0.29)),"Failed object save reports error");check(stored.getAll().equals(beforeFailure),"Failed object save restores data and count together");c.failNextCommit("kepler_object_settings_v1");rejects(()->ObjectSettingsStore.clear(c,"model-obj.obj",-1),"Failed clear reports error");check(stored.getAll().equals(beforeFailure),"Failed clear restores data and count together");
        stored.edit().remove(proof).commit();count=CurrentModelStore.loads;rejects(()->ObjectSettingsStore.snapshot(c),"Legacy data without native-count proof fails closed");check(CurrentModelStore.loads==count,"Missing proof cannot trigger a native import on the UI path");CurrentModelStore.nextMetadata=new JSONObject("{\"objects\":[{}]}");ObjectSettingsStore.Snapshot reopened=ObjectSettingsStore.current(c);check(CurrentModelStore.loads==count+1&&reopened.changes().getDouble("layer_height")==0.22,"Worker reopening rechecks actual native metadata and retains legacy changes");ObjectSettingsStore.save(c,reopened.modelFileName,reopened.plateIndex,reopened.nativeObjectCount,reopened.changes());count=CurrentModelStore.loads;check(ObjectSettingsStore.snapshot(c).nativeObjectCount==1&&CurrentModelStore.loads==count,"Saving reopened object settings repairs count proof");
        stored.edit().putString(proof,"1").commit();Map<String,?> malformedProof=stored.getAll();rejects(()->ObjectSettingsStore.snapshot(c),"String-valued count proof is not trusted");c.failNextCommit("kepler_object_settings_v1");rejects(()->ObjectSettingsStore.save(c,"model-obj.obj",-1,1,saved),"Failed repair reports error");check(stored.getAll().equals(malformedProof),"Failed repair restores the previous proof's exact type");stored.edit().putInt(proof,2).commit();rejects(()->ObjectSettingsStore.snapshot(c),"Multiple-object count proof fails closed");
        ObjectSettingsStore.save(c,"model-obj.obj",-1,1,new JSONObject());check(!stored.getAll().containsKey(id)&&!stored.getAll().containsKey(proof),"Saving empty overrides removes data and count proof");ObjectSettingsStore.save(c,"model-obj.obj",-1,1,saved);ObjectSettingsStore.clear(c,"model-obj.obj",-1);check(!stored.getAll().containsKey(id)&&!stored.getAll().containsKey(proof),"Clear removes both record and proof");
        c.getSharedPreferences("current_model",0).edit().putString("file","model-project.3mf").putString("plate","0").commit();ObjectSettingsStore.save(c,"model-project.3mf",0,1,saved);count=CurrentModelStore.loads;CurrentModelStore.nextMetadata=null;check(ObjectSettingsStore.snapshot(c).nativeObjectCount==1&&CurrentModelStore.loads==count,"Nonempty 3MF fingerprint also avoids native loading");c.getSharedPreferences("current_model",0).edit().putString("plate","1").commit();check(ObjectSettingsStore.snapshot(c).isEmpty(),"Verified count proof cannot leak across plates");
    }
    private static void entry(ZipOutputStream out,String name,String json)throws Exception {out.putNextEntry(new ZipEntry(name));out.write(json.getBytes(StandardCharsets.UTF_8));out.closeEntry();}
}
